Ruin Generator.code:
export function generateRuin(civ:any){
 return {
  id: 'ruin_'+Date.now(),
  origin: civ.id,
  history: civ.history,
  difficulty: civ.power || 1,
  cleared: false,
  lootSeed: Math.random()
 };
}

