export function createDungeonMap(ruin:any){
 const size = 20;
 let map:any[] = [];

 for(let x=0;x<size;x++){
  for(let y=0;y<size;y++){
   map.push({x,y,type:'floor'});
  }
 }

 map.push({x:10,y:10,type:'boss'});
 return map;
}

Loot System (Rare Items).code:
export function generateLoot(ruin:any){
 const rarity = ruin.lootSeed;
 if(rarity > 0.95) return {name:'Ancient Relic', power:100};
 if(rarity > 0.8) return {name:'Epic Artifact', power:50};
 return {name:'Old Gear', power:10};
}

Dungeon Completion Logic.code:
export async function clearDungeon(ruin){
 ruin.cleared = true;

 if(Math.random() > 0.7){
  spawnNewCity(ruin);
 }

 await db.collection('ruins').updateOne({id:ruin.id},{$set:ruin});
}

Rebirth System.code:
function spawnNewCity(ruin){
 return {
  id:'city_'+Date.now(),
  location:ruin.location,
  origin:'reborn_from_ruin'
 };
}

